CREATE TABLE `llx_societe` (`rowid` INT NOT NULL, `nom` VARCHAR(128) NULL, `name_alias` VARCHAR(128) NULL, `client` TINYINT NULL, `fournisseur` TINYINT NULL, `siren` VARCHAR(128) NULL, `siret` VARCHAR(128) NULL, `ape` VARCHAR(128) NULL, `idprof4` VARCHAR(128) NULL, `tva_intra` VARCHAR(20) NULL, `address` VARCHAR(255) NULL, `zip` VARCHAR(25) NULL, `town` VARCHAR(50) NULL, `fk_departement` INT NULL, `fk_pays` INT NULL, `phone` VARCHAR(20) NULL, `email` VARCHAR(128) NULL, `note_private` TEXT NULL, `note_public` TEXT NULL, `status` TINYINT NULL, `cond_reglement` INT NULL, `fk_typent` INT NULL, `entity` INT NULL, `tms` DATETIME NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_socpeople` (`rowid` INT NOT NULL, `fk_soc` INT NULL, `lastname` VARCHAR(50) NULL, `firstname` VARCHAR(50) NULL, `poste` VARCHAR(255) NULL, `email` VARCHAR(255) NULL, `phone` VARCHAR(30) NULL, `phone_mobile` VARCHAR(30) NULL, `address` VARCHAR(255) NULL, `zip` VARCHAR(25) NULL, `town` VARCHAR(255) NULL, `statut` TINYINT NULL, `entity` INT NULL, `tms` DATETIME NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_c_payment_term` (`rowid` INT NOT NULL, `code` VARCHAR(16) NULL, `libelle` VARCHAR(255) NULL, `nbjour` SMALLINT NULL, `type_cdr` TINYINT NULL, `decalage` SMALLINT NULL, `active` TINYINT NULL, `entity` INT NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_bank_account` (`rowid` INT NOT NULL, `ref` VARCHAR(12) NULL, `label` VARCHAR(30) NULL, `bank` VARCHAR(60) NULL, `code_banque` VARCHAR(128) NULL, `code_guichet` VARCHAR(6) NULL, `number` VARCHAR(255) NULL, `cle_rib` VARCHAR(5) NULL, `courant` SMALLINT NULL, `clos` SMALLINT NULL, `entity` INT NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_c_departements` (`rowid` INT NOT NULL, `code_departement` VARCHAR(6) NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_c_typent` (`id` INT NOT NULL, `code` VARCHAR(12) NULL, PRIMARY KEY (`id`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_categorie` (`rowid` INT NOT NULL, `label` VARCHAR(180) NULL, `type` INT NULL, `fk_parent` INT NULL, `entity` INT NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
