CREATE TABLE `llx_product` (`rowid` INT NOT NULL, `ref` VARCHAR(128) NULL, `label` VARCHAR(255) NULL, `fk_product_type` INT NULL, `fk_unit` INT NULL, `customcode` VARCHAR(32) NULL, `fk_country` INT NULL, `seuil_stock_alerte` FLOAT NULL, `tobatch` TINYINT NULL, `tosell` TINYINT NULL, `tobuy` TINYINT NULL, `entity` INT NULL, `tms` DATETIME NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE `llx_product_extrafields` (`fk_object` INT NOT NULL, `elev_garantia` VARCHAR(255) NULL, PRIMARY KEY (`fk_object`)) DEFAULT CHARSET=utf8mb4;
