CREATE TABLE `llx_entrepot` (`rowid` INT NOT NULL, `ref` VARCHAR(255) NULL, `label` VARCHAR(255) NULL, `lieu` VARCHAR(64) NULL, `statut` TINYINT NULL, `fk_parent` INT NULL, `entity` INT NULL, PRIMARY KEY (`rowid`)) DEFAULT CHARSET=utf8mb4;
